    $path=realpath(__DIR__.'/.medicine321a-validation/data');
    if(!$path||!str_starts_with($meta['version'],'10.4.27-')||(int)$meta['port']!==3341||strcasecmp(rtrim(str_replace('\\','/',$meta['datadir']),'/'),str_replace('\\','/',$path))!==0||$meta['mode']!==M321A_MODE||$meta['global_mode']!==M321A_MODE){throw new RuntimeException('Disposable bootstrap isolation guard failed.');}
    return $pdo;
}
function m321aObjects(PDO $pdo):array {
    $db=(new ReflectionClass(App\Core\Database::class))->newInstanceWithoutConstructor();(new ReflectionProperty(App\Core\Database::class,'pdo'))->setValue($db,$pdo);
