}
function m321aSqlReject(callable $op,array $codes=[4025,1644]):void {try{$op();}catch(PDOException $e){medicineCheck(in_array((int)($e->errorInfo[1]??0),$codes,true));return;}throw new RuntimeException('Forbidden SQL accepted.');}
function m321aRace(array $jobs):array {
    $work=__DIR__.'/.medicine321a-validation';foreach(['ready1','ready2','go'] as $name){if(is_file($work.'/'.$name)){unlink($work.'/'.$name);}}
    $processes=[];foreach($jobs as $n=>$job){file_put_contents($work.'/job'.$n.'.json',json_encode($job,JSON_THROW_ON_ERROR));$processes[$n]=proc_open([PHP_BINARY,__FILE__,'worker',(string)$n],[0=>['pipe','r'],1=>['file',$work.'/out'.$n.'.json','w'],2=>['file',$work.'/err'.$n,'w']],$pipes);if(!is_resource($processes[$n])){throw new RuntimeException('Worker unavailable.');}fclose($pipes[0]);}
    $deadline=microtime(true)+20;while(!is_file($work.'/ready1')||!is_file($work.'/ready2')){if(microtime(true)>$deadline){throw new RuntimeException('Barrier timeout.');}usleep(10000);}file_put_contents($work.'/go','go');
    $results=[];foreach($processes as $n=>$p){medicineCheck(proc_close($p)===0,'Worker failed.');$results[]=json_decode(file_get_contents($work.'/out'.$n.'.json'),true,64,JSON_THROW_ON_ERROR);}return $results;
}
