$source=file_get_contents(dirname(__DIR__).'/database/structure.sql');
$newCheck="CONSTRAINT `chk_medicine_grant_active` CHECK (is_active IN (0,1) AND ((expires_at IS NOT NULL AND expires_at > granted_at) OR (expires_at IS NULL AND BINARY capability=BINARY 'administrator' AND BINARY scope=BINARY 'catalog' AND user_id=granted_by AND qualification_reference IS NULL AND qualification_assessed_by IS NULL AND qualification_scope IS NULL)))";
