$prior=str_replace([$newCheck,'`expires_at` datetime(6) DEFAULT NULL,'],["CONSTRAINT `chk_medicine_grant_active` CHECK (is_active IN (0,1) AND expires_at > granted_at)",'`expires_at` datetime(6) NOT NULL,'],$source);
