$omit=["/*!40101 SET SQL_MODE=''*/;","/*!40101 SET @OLD_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_AUTO_VALUE_ON_ZERO' */;","/*!40101 SET SQL_MODE=@OLD_SQL_MODE */;"];$buffer='';$delimiter=';';$count=0;$skipped=[];
foreach(preg_split('/\r?\n/',$prior) as $line){if(in_array(trim($line),$omit,true)){$skipped[]=trim($line);continue;}if(preg_match('/^\s*DELIMITER\s+(\S+)\s*$/i',$line,$m)){$delimiter=$m[1];continue;}$buffer.=$line."\n";$trim=rtrim($buffer);if(str_ends_with($trim,$delimiter)){$pdo->exec(substr($trim,0,-strlen($delimiter)));$count++;$buffer='';}}
if(trim($buffer)!==''||count($skipped)!==3){throw new RuntimeException('Import accounting failed.');}
$beforeTables=$pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$beforeTriggers=$pdo->query('SELECT TRIGGER_NAME,ACTION_STATEMENT,SQL_MODE FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() ORDER BY TRIGGER_NAME')->fetchAll();
$beforeDefinitions=[];foreach($beforeTables as $table){$beforeDefinitions[$table]=$pdo->query('SHOW CREATE TABLE `'.$table.'`')->fetch()['Create Table']??$pdo->query('SHOW CREATE VIEW `'.$table.'`')->fetch()['Create View'];}
